/**
 * The content mirror: every fact this server serves.
 *
 * data/site-mirror.json is generated by scripts/sync-content.mjs directly from
 * the KanchanFlow website repository. Nothing in this module invents a value.
 * If a tool cannot find something here it reports NOT_FOUND — it does not
 * substitute a plausible answer, which is the single most important property
 * of this server.
 *
 * Loading is lazy and cached: the file is ~750 KB, and a stdio session that
 * only reads a reference document should never pay to parse it.
 */

import fs from "node:fs";

import { packagePath } from "../utils/package-paths.js";
import type { Feature, Integration, SiteMirror, BlogPost, GlossaryTerm } from "./types.js";

let cache: SiteMirror | null = null;

/** Index maps, built once alongside the mirror. */
interface Indexes {
  featureBySlug: Map<string, Feature>;
  integrationBySlug: Map<string, Integration>;
  postBySlug: Map<string, BlogPost>;
  termBySlug: Map<string, GlossaryTerm>;
}
let indexes: Indexes | null = null;

export const MIRROR_FILE = "data/site-mirror.json";

export function loadMirror(): SiteMirror {
  if (cache) return cache;

  const file = packagePath(MIRROR_FILE);
  let raw: string;
  try {
    raw = fs.readFileSync(file, "utf8");
  } catch {
    throw new Error(
      `Content mirror not found at ${MIRROR_FILE}. Run \`npm run sync\` against the KanchanFlow website repository.`
    );
  }

  const parsed = JSON.parse(raw) as SiteMirror;
  if (!parsed?.meta?.mirrorVersion || !parsed.brand?.name) {
    throw new Error(`Content mirror at ${MIRROR_FILE} is not a valid KanchanFlow mirror.`);
  }

  cache = parsed;
  indexes = {
    featureBySlug: new Map(parsed.features.items.map((f) => [f.slug, f])),
    integrationBySlug: new Map(parsed.integrations.items.map((i) => [i.slug, i])),
    postBySlug: new Map(parsed.blog.posts.map((p) => [p.slug, p])),
    termBySlug: new Map(parsed.glossary.terms.map((t) => [t.slug, t])),
  };
  return cache;
}

function idx(): Indexes {
  if (!indexes) loadMirror();
  return indexes as Indexes;
}

export const getFeature = (slug: string): Feature | undefined => idx().featureBySlug.get(slug);
export const getIntegration = (slug: string): Integration | undefined =>
  idx().integrationBySlug.get(slug);
export const getPost = (slug: string): BlogPost | undefined => idx().postBySlug.get(slug);
export const getTerm = (slug: string): GlossaryTerm | undefined => idx().termBySlug.get(slug);

/** Test seam. Drops the cache so a later load re-reads the file. */
export function resetMirrorCache(): void {
  cache = null;
  indexes = null;
}

/**
 * Suggest close slugs for a miss, so a NOT_FOUND tells the client what it
 * probably meant instead of ending the conversation.
 */
export function suggestSlugs(wanted: string, available: readonly string[], limit = 5): string[] {
  const needle = wanted.toLowerCase().trim();
  if (!needle) return available.slice(0, limit) as string[];
  const scored = available
    .map((slug) => {
      const s = slug.toLowerCase();
      let score = 0;
      if (s === needle) score = 100;
      else if (s.startsWith(needle) || needle.startsWith(s)) score = 80;
      else if (s.includes(needle) || needle.includes(s)) score = 60;
      else {
        const parts = needle.split(/[-_\s]+/).filter(Boolean);
        score = parts.filter((p) => p.length > 2 && s.includes(p)).length * 15;
      }
      return { slug, score };
    })
    .filter((x) => x.score > 0)
    .sort((a, b) => b.score - a.score);
  return scored.slice(0, limit).map((x) => x.slug);
}
